def is_6_regular_good(n, k, m):
    # A 6-regular graph has n*6/2 edges.
    # For n=15, it's 45.
    # Let's check if there's a 6-regular graph where every 7 vertices have <= 9 edges.
    # A 6-regular graph can be constructed as a circulant graph C_15(1, 2, 3)? No, that's 6-regular.
    # C_15(1, 2, 3) has degree 2*3 = 6.
    adj = [[False]*n for _ in range(n)]
    for i in range(n):
        for step in [1, 2, 3]:
            adj[i][(i+step)%n] = adj[i][(i-step)%n] = True

    from itertools import combinations
    for combo in combinations(range(n), k):
        if count_edges_in_subgraph(adj, combo) > m:
            return False
    return True

print(f"Is C_15(1, 2, 3) good for f(15, 7, 9)? {is_6_regular_good(15, 7, 9)}")

