def check_circulant(n, steps, k, m):
    adj = [[False]*n for _ in range(n)]
    for i in range(n):
        for step in steps:
            adj[i][(i+step)%n] = adj[i][(i-step)%n] = True

    for combo in itertools.combinations(range(n), k):
