import itertools
import random

def count_edges_in_subsets(adj, n, m):
    max_e = 0
    for subset in itertools.combinations(range(n), m):
        e = 0
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if adj[subset[i]][subset[j]]:
                    e += 1
        if e > max_e:
            max_e = e
    return max_e

def solve():
    n = 15
    m = 7
    edges_needed = 49
    max_e_allowed = 10

    # Try random graphs
    for _ in range(1000):
        adj = [[False]*n for _ in range(n)]
        edges = []
        all_possible_edges = list(itertools.combinations(range(n), 2))
        random.shuffle(all_possible_edges)
        edges = all_possible_edges[:edges_needed]

        for u, v in edges:
            adj[u][v] = adj[v][u] = True

        if count_edges_in_subsets(adj, n, m) <= max_e_allowed:
            return True, count_edges_in_subsets(adj, n, m)
    return False, None

print(solve())

