    def get_max_edges_fast(graph):
        max_e = 0
        for nodes in itertools.combinations(range(N), k):
            subgraph = graph.subgraph(nodes)
            max_e = max(max_e, subgraph.number_of_edges())
        return max_e

    current_max = get_max_edges_fast(G)
    if current_max <= 15:
        return current_max

    for _ in range(500):
        edges = list(G.edges())
        u1, v1 = random.choice(edges)
        u2, v2 = random.sample(range(N), 2)
        if not G.has_edge(u2, v2):
            G.remove_edge(u1, v1)
            G.add_edge(u2, v2)
            new_max = get_max_edges_fast(G)
            if new_max < current_max:
                current_max = new_max
            else:
                G.remove_edge(u2, v2)
                G.add_edge(u1, v1)
    return current_max

